import { Component, type ErrorInfo, type ReactNode } from 'react';

/**
 * Contains a render failure to the section that caused it.
 *
 * A malformed field used to take down the entire page: one team-side arrived as
 * `{}` instead of `[]`, `.map` threw, the exception escaped uncaught and React
 * unmounted the whole tree — a blank site from one missing value. Data is
 * generated by a separate R pipeline, so the site cannot assume it is
 * well-formed; it can only refuse to let one bad report cost the other ten.
 */
interface Props { children: ReactNode; name?: string }
interface State { err: Error | null }

export class SectionBoundary extends Component<Props, State> {
  state: State = { err: null };

  static getDerivedStateFromError(err: Error): State { return { err }; }

  componentDidCatch(err: Error, info: ErrorInfo) {
    // Keep the detail in the console — the card stays deliberately quiet.
    console.error(`[section: ${this.props.name ?? 'unknown'}]`, err, info.componentStack);
  }

  render() {
    if (!this.state.err) return this.props.children;
    return (
      <section className="rounded-2xl border border-loss/30 bg-loss/5 px-4 py-3">
        <div className="text-[10px] uppercase tracking-wider text-loss font-semibold">
          {this.props.name ?? 'Section'} unavailable
        </div>
        <p className="mt-1 text-xs text-text-secondary">
          This report couldn’t be rendered — most likely a malformed field from the
          data pipeline. Everything else on the page is unaffected.
        </p>
        <p className="mt-1 font-mono text-[10px] text-text-muted break-words">
          {this.state.err.message}
        </p>
      </section>
    );
  }
}
